{
  "components": [
    {
      "description": "HTTP handlers for browsing/searching the catalog and processing checkout requests.",
      "id": "api",
      "name": "API",
      "contained_modules:": [
        "bookshop",
        "bookshop.api",
        "bookshop.api.catalog_routes",
        "bookshop.api.checkout_routes"
      ]
    },
    {
      "description": "Use‑case services that orchestrate domain logic with infrastructure adapters.",
      "id": "application",
      "name": "Application",
      "contained_modules:": [
        "bookshop.application",
        "bookshop.application.checkout",
        "bookshop.application.inventory"
      ]
    },
    {
      "description": "Pure domain model: entities, aggregates, and pricing rules.",
      "id": "domain",
      "name": "Domain",
      "contained_modules:": [
        "bookshop.domain",
        "bookshop.domain.book",
        "bookshop.domain.catalog",
        "bookshop.domain.order",
        "bookshop.domain.pricing"
      ]
    },
    {
      "description": "In‑memory persistence adapters and external service stubs.",
      "id": "infrastructure",
      "name": "Infrastructure",
      "contained_modules:": [
        "bookshop.infrastructure",
        "bookshop.infrastructure.book_repository",
        "bookshop.infrastructure.order_repository",
        "bookshop.infrastructure.payment_gateway"
      ]
    }
  ],
  "relations": [
    { "from": "api", "to": "application" },
    { "from": "api", "to": "domain" },
    { "from": "application", "to": "domain" },
    { "from": "application", "to": "infrastructure" },
    { "from": "infrastructure", "to": "domain" }
  ]
}
